const $ = <T extends HTMLElement = HTMLElement>(selector: string) => document.querySelector<T>(selector)!;
const state = { view: 'drive' as View, path: '', selected: new Set<string>(), items: [] as FileItem[], viewMode: (localStorage.getItem('cloud-view') ?? 'grid') as 'grid' | 'list', sort: 'name', direction: 'asc', uploads: [] as UploadRecord[], searchTimer: 0, syncRefreshTimer: 0, clipboard: null as { ids: string[]; mode: 'cut' | 'copy' } | null, searchFilters: {} as Record<string, string>, lastSearch: '', gallery: [] as FileItem[] };
