type SyncProgressView = { initial: boolean; phase: string; filesDone: number; filesTotal: number; foldersDone: number; foldersTotal: number; bytesDone: number; bytesTotal: number; excludedFiles: number; excludedFolders: number };
type SyncMappingView = { id: string; cloudPath: string; localPath: string; policy: { preset: 'project' | 'exact'; exclude: string[] }; paused: boolean; status: string; lastError: string | null; progress: SyncProgressView | null };
type SyncDeviceView = { id: string; name: string; platform: string; clientVersion: string; lastSeenAt: string; revokedAt: string | null; mappings: SyncMappingView[] };
type PairingView = { id: string; code: string; cloudPath: string; expiresAt: string };
